"""vad_calib — 真实录音批量校准：①判定停止的窗口 ②预滚/句首余量

① 停止窗：只统计句中停顿（首语音帧之后、末语音帧之前）→ 取"切碎率≤目标"的最小窗，
   同时写 silero 的 required_misses(32ms/帧) 与另一后端 Segmenter 的 vad_silence_ms(30ms/帧)。
② 预滚：测每条录音【段首静音长度】(首语音帧之前) 与【段首能量比】(段首100ms RMS/整段RMS)。
   段首能量比越高 ⇒ 越可能把起音切掉了（本仓血债判据：旧值 0.67×、新值 0.00×）。
   据此给 ahead_cap_ms / ahead_frac / onset_margin_ms 的推荐值。

用法:
  python -m opencode_fastpath.vad_calib --glob "utt/*_mic_*.wav" --n 200
  ... --save-profile alice          # 写说话人档案（运行时自动加载）
  ... --apply aoe4|ops|office       # 直接写进 profile 配置（5 个键一起）
"""
from __future__ import annotations

import argparse
import glob
import io
import json
import random
import re
import wave
from pathlib import Path

import numpy as np

ROOT = Path(__file__).resolve().parent.parent
FRAME, SR = 512, 16000
MS = FRAME / SR * 1000.0
PROB_THR, SMOOTH = 0.4, 3
GRID = list(range(5, 31))


def _rd(p):
    with wave.open(str(p), "rb") as w:
        raw = w.readframes(w.getnframes())
        sr, ch = w.getframerate(), w.getnchannels()
    x = np.frombuffer(raw, dtype="<i2").astype(np.float32) / 32768.0
    return (x.reshape(-1, ch)[:, 0] if ch > 1 else x), sr


def _engine():
    from vad_silero import SileroVADEngine
    return SileroVADEngine(pre_gain=True, target_rms=0.03, max_gain=60.0,
                           prob_threshold=PROB_THR, db_threshold=0, required_hits=2,
                           smoothing_window=SMOOTH, max_speech_ms=6000, required_misses=22)


def analyze_arrays(bufs, min_speech_frames=3):
    """→ dict(pauses, n_files, head_ms, head_ratio, seg_len_ms, peaks)"""
    eng = _engine()
    pauses, heads, ratios, segs, peaks = [], [], [], [], []
    ok = 0
    for x in bufs:
        if x is None or len(x) < SR * 0.4:
            continue
        eng.reset()
        probs = []
        for i in range(0, len(x) - FRAME + 1, FRAME):
            eng.push(x[i:i + FRAME])
            probs.append(eng.last_prob)
        sm = [float(np.mean(probs[max(0, i - SMOOTH + 1):i + 1])) for i in range(len(probs))]
        sp = [i for i, v in enumerate(sm) if v >= PROB_THR]
        if len(sp) < min_speech_frames:
            continue
        ok += 1
        a, b = sp[0], sp[-1]
        run = 0
        for i in range(a, b + 1):
            if sm[i] < PROB_THR:
                run += 1
            else:
                if run:
                    pauses.append(run * MS)
                run = 0
        if run:
            pauses.append(run * MS)
        xw = x[:len(sm) * FRAME]
        head = xw[:min(len(xw), int(0.10 * SR))]
        rms_all = float(np.sqrt(np.mean(xw ** 2))) if xw.size else 0.0
        rms_head = float(np.sqrt(np.mean(head ** 2))) if head.size else 0.0
        heads.append(a * MS)
        ratios.append(rms_head / rms_all if rms_all > 1e-9 else 0.0)
        segs.append(len(xw) / SR * 1000.0)
        peaks.append(float(np.abs(xw).max()) if xw.size else 0.0)
    return {"pauses": pauses, "n_files": ok, "head_ms": heads,
            "head_ratio": ratios, "seg_len_ms": segs, "peaks": peaks}


def analyze(files):
    bufs = []
    for p in files:
        try:
            x, sr = _rd(p)
        except Exception:
            continue
        if len(x) >= SR * 0.4:
            bufs.append(x)
    return analyze_arrays(bufs)


def pct(lst, q):
    if not lst:
        return 0.0
    s = sorted(lst)
    return s[min(len(s) - 1, int(len(s) * q))]


def recommend_asr_gain(peaks, target=0.6):
    """ASR 前增益上限：让 90% 的真实录音都能把峰值拉到 target（0.6）
       cap = ceil(target / p10(peak))，夹到 [60, 600]
    """
    if not peaks:
        return None
    p10 = pct(peaks, 0.10)
    if p10 <= 1e-6:
        return None
    cap = int(min(600, max(60, np.ceil(target / p10))))
    return {"asr_gain_cap": cap, "peak_p10": round(p10, 5),
            "peak_p50": round(pct(peaks, 0.5), 5), "need_gain_p90": round(target / p10, 1)}


def recommend(pauses, n_files, target=3.0):
    best, table = None, []
    for m in GRID:
        w = m * MS
        rate = 100.0 * sum(1 for v in pauses if v >= w) / max(1, n_files)
        table.append((m, w, rate))
        if best is None and rate <= target:
            best = (m, w, rate)
    return best, table


def recommend_preroll(res, keep_extra_ms=120.0):
    """预滚/句首余量推荐：让"保留的静音"覆盖绝大多数录音的段首静音"""
    heads, ratios, segs = res["head_ms"], res["head_ratio"], res["seg_len_ms"]
    clipped = 100.0 * sum(1 for r in ratios if r > 0.35) / max(1, len(ratios))
    need = pct(heads, 0.90) + keep_extra_ms               # p90 段首静音 + 余量
    margin = int(max(80, min(250, pct(heads, 0.90) + 50)))
    cap = int(max(300, min(640, need)))          # VAD 只给 640ms，cap 不能超过它
    frac = round(max(0.10, min(0.50, need / max(1.0, pct(segs, 0.50)))), 3)
    return {"onset_margin_ms": margin, "ahead_cap_ms": cap, "ahead_frac": frac,
            "head_p50": pct(heads, .5), "head_p90": pct(heads, .9),
            "head_ratio_p90": pct(ratios, .9), "onset_clip_rate": clipped,
            "seg_p50": pct(segs, .5)}


def apply_to_profile(which: str, misses: int, note: str, pre=None):
    prof = {"aoe4": ROOT / "aoe4/profiles/aoe4-v1/intent_config.aoe4.json",
            "ops": ROOT / "ops/profiles/ops-v1/intent_config.ops.json",
            "office": ROOT / "intent_config.json"}.get(which)
    if prof is None or not prof.exists():
        print("!! 未知 profile:", which)
        return
    s = io.open(prof, encoding="utf-8").read()
    m = re.search(r'"vad_required_misses":\s*(\d+)', s)
    if not m:
        print("!! 配置里没有 vad_required_misses:", prof)
        return
    old = m.group(1)
    ms = int(misses) * 32
    s = re.sub(r'"vad_required_misses":\s*\d+', f'"vad_required_misses": {misses}', s, count=1)
    if re.search(r'"vad_silence_ms":\s*\d+', s):
        s = re.sub(r'"vad_silence_ms":\s*\d+', f'"vad_silence_ms": {ms}', s, count=1)
    else:
        s = s.replace(f'"vad_required_misses": {misses},',
                      f'"vad_required_misses": {misses},\n    "vad_silence_ms": {ms},', 1)

    def put(key, val):
        nonlocal s
        if re.search(rf'"{key}":\s*[0-9.]+', s):
            s = re.sub(rf'"{key}":\s*[0-9.]+', f'"{key}": {val}', s, count=1)
        else:
            s = s.replace(f'"vad_silence_ms": {ms},', f'"vad_silence_ms": {ms},\n    "{key}": {val},', 1)

    if pre:
        put("onset_margin_ms", pre["onset_margin_ms"])
        put("ahead_cap_ms", min(640, int(pre["ahead_cap_ms"])))
        put("ahead_frac", pre["ahead_frac"])
    if pre and pre.get("asr_gain_cap"):
        put("asr_gain_cap", max(200, int(pre["asr_gain_cap"])))   # 保底 200：小声时靠它
    if "_comment_vad_misses" not in s:
        s = s.replace(f'"vad_required_misses": {misses},',
                      f'"vad_required_misses": {misses},\n    "_comment_vad_misses": "{note}",', 1)
    io.open(prof, "w", encoding="utf-8").write(s)
    json.load(io.open(prof, encoding="utf-8"))
    extra = (f"；预滚 onset_margin={pre['onset_margin_ms']}ms cap={pre['ahead_cap_ms']}ms "
             f"frac={pre['ahead_frac']}") if pre else ""
    print(f"[OPENCODE] 已写入 {which}: vad_required_misses {old} → {misses}"
          f"（{int(old)*32}→{ms}ms）；vad_silence_ms → {ms}ms{extra}")


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--glob", default="utt/*_mic_*.wav")
    ap.add_argument("--n", type=int, default=200)
    ap.add_argument("--target", type=float, default=3.0)
    ap.add_argument("--seed", type=int, default=23)
    ap.add_argument("--save-profile", default=None)
    ap.add_argument("--apply", default=None, choices=["aoe4", "ops", "office"])
    a = ap.parse_args()

    files = sorted(glob.glob(str(ROOT / a.glob)))
    random.seed(a.seed)
    if a.n and len(files) > a.n:
        files = random.sample(files, a.n)
    res = analyze(files)
    if not res["n_files"]:
        print("!! 没有可用录音")
        return 1
    pa, nf = res["pauses"], res["n_files"]
    print(f"真实录音 {nf} 条｜句中停顿 {len(pa)} 个｜"
          f"p50={pct(pa,.5):.0f} p90={pct(pa,.9):.0f} p95={pct(pa,.95):.0f} ms")

    best, table = recommend(pa, nf, a.target)
    print(f"\n[停止窗] {'misses':>7} {'静音窗':>8} {'切碎率':>8}")
    for m, w, rate in table[::3]:
        mark = "  ← 推荐" if best and m == best[0] else ""
        print(f"{m:>14} {w:>6.0f}ms {rate:>7.1f}%{mark}")
    if not best:
        print("!! 所有候选都超过目标切碎率")
        return 1
    m, w, rate = best
    print(f"推荐: required_misses={m}（{w:.0f}ms）→ 切碎 {rate:.1f}%，判停延迟 +{w:.0f}ms")

    pre = recommend_preroll(res)
    pre.update(recommend_asr_gain(res["peaks"]) or {})
    print(f"\n[预滚/句首] 段首静音 p50={pre['head_p50']:.0f}ms p90={pre['head_p90']:.0f}ms｜"
          f"段首能量比 p90={pre['head_ratio_p90']:.2f}｜疑似切掉起音 {pre['onset_clip_rate']:.0f}%")
    print(f"推荐: onset_margin_ms={pre['onset_margin_ms']}（起点前后余量） "
          f"ahead_cap_ms={pre['ahead_cap_ms']}（预滚保留上限） ahead_frac={pre['ahead_frac']}（=总长×比例）")
    if pre.get("asr_gain_cap"):
        print(f"[ASR 前增益] 峰值 p10={pre['peak_p10']:.4f} p50={pre['peak_p50']:.4f} → "
              f"需要 {pre['need_gain_p90']:.0f}× 才能归一到 0.6 ⇒ 推荐 asr_gain_cap={pre['asr_gain_cap']}"
              f"（当前默认 200；实测 60× 在极小声时空转 12%）")
    print("     读法：段首能量比>0.35 视为「起音被切」；cap/frac 越大保留越多（代价：多送静音给 ASR）")

    note = (f"校准({nf}条真实录音): 停顿 p90={pct(pa,.9):.0f}ms; 本值预计切碎 {rate:.1f}%")
    if a.save_profile:
        from .vad_adapt import save as _save
        rec = _save(m, "calib", a.save_profile,
                    extra={"n_files": nf, "p90": pct(pa, .9), "p95": pct(pa, .95),
                           "cut_rate": rate, **pre})
        print(f"[OPENCODE] 已写入说话人档案 {a.save_profile}: {json.dumps(rec, ensure_ascii=False)}")
    if a.apply:
        apply_to_profile(a.apply, m, note, pre)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
